    "validatedWormStorageAccountResourceId": "[if(and(and(and(and(and(and(and(and(and(and(equals(length(variables('wormStorageAccountResourceIdSegments')), 9), empty(variables('wormStorageAccountResourceIdSegments')[0])), equals(toLower(variables('wormStorageAccountResourceIdSegments')[1]), 'subscriptions')), equals(variables('wormStorageAccountResourceIdSegments')[2], parameters('subscriptionId'))), equals(toLower(variables('wormStorageAccountResourceIdSegments')[3]), 'resourcegroups')), not(empty(variables('wormStorageAccountResourceIdSegments')[4]))), equals(toLower(variables('wormStorageAccountResourceIdSegments')[5]), 'providers')), equals(toLower(variables('wormStorageAccountResourceIdSegments')[6]), 'microsoft.storage')), equals(toLower(variables('wormStorageAccountResourceIdSegments')[7]), 'storageaccounts')), not(empty(variables('wormStorageAccountName')))), equals(toLower(resourceId(parameters('subscriptionId'), variables('wormStorageAccountResourceIdSegments')[4], 'Microsoft.Storage/storageAccounts', variables('wormStorageAccountName'))), toLower(parameters('wormStorageAccountResourceId')))), parameters('wormStorageAccountResourceId'), fail('WORM storage account resource ID is not an authoritative storage account ID in the owner-bound subscription.'))]",
    "coordinationStorageAccountResourceId": "[resourceId('Microsoft.Storage/storageAccounts', parameters('storageAccountName'))]",
    "validatedStorageAccountName": "[if(and(and(and(and(and(and(not(empty(variables('validatedDeploymentScope'))), not(equals(toLower(variables('coordinationStorageAccountResourceId')), toLower(variables('validatedBffStorageAccountResourceId'))))), not(equals(toLower(variables('coordinationStorageAccountResourceId')), toLower(variables('validatedWormStorageAccountResourceId'))))), not(equals(toLower(variables('validatedBffStorageAccountResourceId')), toLower(variables('validatedWormStorageAccountResourceId'))))), not(equals(toLower(parameters('storageAccountName')), toLower(variables('bffStorageAccountName'))))), not(equals(toLower(parameters('storageAccountName')), toLower(variables('wormStorageAccountName'))))), not(equals(toLower(variables('bffStorageAccountName')), toLower(variables('wormStorageAccountName'))))), parameters('storageAccountName'), fail('Performance coordination, BFF, and WORM storage accounts must be pairwise distinct.'))]",
    "isolationSuffix": "[uniqueString(subscription().tenantId, resourceGroup().id, variables('validatedStorageAccountName'))]",
    "bootstrapLeaseDataRoleDefinitionGuid": "[guid(subscription().id, resourceGroup().id, variables('validatedStorageAccountName'), variables('containerName'), 'nac-bff-performance-lease-bootstrap-read-add-v1')]",
    "runtimeLeaseDataRoleDefinitionGuid": "[guid(subscription().id, resourceGroup().id, variables('validatedStorageAccountName'), variables('containerName'), 'nac-bff-performance-lease-runtime-read-write-v1')]",
    "blobReadDataAction": "Microsoft.Storage/storageAccounts/blobServices/containers/blobs/read",
    "blobAddDataAction": "Microsoft.Storage/storageAccounts/blobServices/containers/blobs/add/action",
    "blobWriteDataAction": "Microsoft.Storage/storageAccounts/blobServices/containers/blobs/write",
    "exactBootstrapLeaseBlobCondition": "[format('((!(ActionMatches{{''{0}''}}) AND !(ActionMatches{{''{1}''}})) OR (@Resource[Microsoft.Storage/storageAccounts/blobServices/containers:name] StringEquals ''{2}'' AND @Resource[Microsoft.Storage/storageAccounts/blobServices/containers/blobs:path] StringEquals ''{3}''))', variables('blobReadDataAction'), variables('blobAddDataAction'), variables('containerName'), variables('leaseBlobPath'))]",
    "exactRuntimeLeaseBlobCondition": "[format('((!(ActionMatches{{''{0}''}}) AND !(ActionMatches{{''{1}''}})) OR (@Resource[Microsoft.Storage/storageAccounts/blobServices/containers:name] StringEquals ''{2}'' AND @Resource[Microsoft.Storage/storageAccounts/blobServices/containers/blobs:path] StringEquals ''{3}''))', variables('blobReadDataAction'), variables('blobWriteDataAction'), variables('containerName'), variables('leaseBlobPath'))]",
    "validatedBootstrapPrincipalId": "[if(and(not(equals(toLower(parameters('bootstrapPrincipalId')), toLower(parameters('runtimePrincipalId')))), not(equals(parameters('bootstrapCertificateSha256'), parameters('runtimeCertificateSha256')))), parameters('bootstrapPrincipalId'), fail('Bootstrap and runtime principal and certificate identities must be different.'))]",
    "validatedRuntimePrincipalId": "[if(and(not(equals(toLower(parameters('bootstrapPrincipalId')), toLower(parameters('runtimePrincipalId')))), not(equals(parameters('bootstrapCertificateSha256'), parameters('runtimeCertificateSha256')))), parameters('runtimePrincipalId'), fail('Bootstrap and runtime principal and certificate identities must be different.'))]",
    "mandatoryResourceTags": {
      "blobPrecreation": "owner-gated-before-runtime",
      "dataClassification": "synthetic-only",
      "environment": "test",
      "managedBy": "bicep",
      "storageBoundary": "dedicated-from-bff-and-worm",
      "targetBindingSha256": "[parameters('targetBindingSha256')]",
      "workload": "nac-bff-performance-coordination"
    },
    "resourceTags": "[union(parameters('tags'), variables('mandatoryResourceTags'))]"
  },
  "resources": [
    {
      "type": "Microsoft.Storage/storageAccounts",
      "apiVersion": "2023-05-01",
      "name": "[variables('validatedStorageAccountName')]",
      "location": "[parameters('location')]",
      "tags": "[variables('resourceTags')]",
      "kind": "StorageV2",
      "sku": {
        "name": "Standard_LRS"
      },
      "properties": {
        "accessTier": "Hot",
        "allowBlobPublicAccess": false,
        "allowCrossTenantReplication": false,
        "allowSharedKeyAccess": false,
        "defaultToOAuthAuthentication": true,
        "isHnsEnabled": false,
        "minimumTlsVersion": "TLS1_2",
        "publicNetworkAccess": "Enabled",
        "supportsHttpsTrafficOnly": true,
        "networkAcls": {
          "bypass": "None",
          "defaultAction": "Deny",
          "ipRules": [
            {
              "action": "Allow",
              "value": "[parameters('allowedClientIpAddress')]"
            }
          ],
          "resourceAccessRules": [],
          "virtualNetworkRules": []
        }
      }
    },
    {
      "type": "Microsoft.Storage/storageAccounts/blobServices",
      "apiVersion": "2023-05-01",
      "name": "[format('{0}/{1}', variables('validatedStorageAccountName'), 'default')]",
      "properties": {
        "isVersioningEnabled": false,
        "deleteRetentionPolicy": {
          "enabled": false
        },
        "containerDeleteRetentionPolicy": {
          "enabled": false
        }
      },
      "dependsOn": [
        "[resourceId('Microsoft.Storage/storageAccounts', variables('validatedStorageAccountName'))]"
      ]
    },
    {
      "type": "Microsoft.Storage/storageAccounts/blobServices/containers",
      "apiVersion": "2023-05-01",
      "name": "[format('{0}/{1}/{2}', variables('validatedStorageAccountName'), 'default', variables('containerName'))]",
      "properties": {
        "publicAccess": "None",
        "metadata": {
          "nac_schema_version": "nac.azure-bff-performance-coordination/v1",
          "data_classification": "synthetic-only",
          "lease_blob_path": "[variables('leaseBlobPath')]",
          "lease_blob_type": "BlockBlob",
          "lease_blob_content_length": "0",
          "lease_blob_bootstrap": "owner-gated-put-if-absent-before-runtime",
          "bootstrap_authorization": "blob-read-plus-add-only-no-write-no-delete",
          "runtime_authorization": "blob-read-plus-write-only-no-add-no-delete",
          "azure_blob_write_authorization": "runtime-write-includes-create-overwrite-lease-and-break",
          "operation_restriction_boundary": "sealed-app-api-defense-in-depth-not-azure-enforced",
          "principal_separation": "distinct-owner-bound-bootstrap-and-runtime-principals"
        }
      },
      "dependsOn": [
        "[resourceId('Microsoft.Storage/storageAccounts/blobServices', variables('validatedStorageAccountName'), 'default')]"
      ]
