        "roleName": "[format('NaC BFF Performance Lease Bootstrap Read Add {0}', variables('isolationSuffix'))]",
        "description": "Bootstrap-only read/add on one ABAC-conditioned blob path. Write, delete, ownership, and container management are excluded.",
        "type": "CustomRole",
        "permissions": [
          {
            "actions": [],
            "notActions": [],
            "dataActions": [
              "Microsoft.Storage/storageAccounts/blobServices/containers/blobs/read",
              "Microsoft.Storage/storageAccounts/blobServices/containers/blobs/add/action"
            ],
            "notDataActions": []
          }
        ],
        "assignableScopes": [
          "[resourceGroup().id]"
        ]
      }
    },
    {
      "type": "Microsoft.Authorization/roleDefinitions",
      "apiVersion": "2022-04-01",
      "name": "[variables('runtimeLeaseDataRoleDefinitionGuid')]",
      "properties": {
        "roleName": "[format('NaC BFF Performance Lease Runtime Read Write {0}', variables('isolationSuffix'))]",
        "description": "Runtime-only read/write on one ABAC-conditioned blob path. Add, delete, ownership, and container management are excluded; write includes overwrite and lease operations.",
        "type": "CustomRole",
        "permissions": [
          {
            "actions": [],
            "notActions": [],
            "dataActions": [
              "Microsoft.Storage/storageAccounts/blobServices/containers/blobs/read",
              "Microsoft.Storage/storageAccounts/blobServices/containers/blobs/write"
            ],
            "notDataActions": []
          }
        ],
        "assignableScopes": [
          "[resourceGroup().id]"
        ]
      }
    },
    {
      "type": "Microsoft.Authorization/roleAssignments",
      "apiVersion": "2022-04-01",
      "scope": "[resourceId('Microsoft.Storage/storageAccounts/blobServices/containers', variables('validatedStorageAccountName'), 'default', variables('containerName'))]",
      "name": "[guid(resourceId('Microsoft.Storage/storageAccounts/blobServices/containers', variables('validatedStorageAccountName'), 'default', variables('containerName')), variables('validatedBootstrapPrincipalId'), resourceId('Microsoft.Authorization/roleDefinitions', variables('bootstrapLeaseDataRoleDefinitionGuid')), variables('leaseBlobPath'))]",
      "properties": {
