      "properties": {
        "condition": "[variables('exactRuntimeLeaseBlobCondition')]",
        "conditionVersion": "2.0",
        "description": "Runtime-only read/write authorization scoped to the exact NaC BFF performance lease blob path; blob add and delete are excluded.",
        "principalId": "[variables('validatedRuntimePrincipalId')]",
        "principalType": "ServicePrincipal",
        "roleDefinitionId": "[resourceId('Microsoft.Authorization/roleDefinitions', variables('runtimeLeaseDataRoleDefinitionGuid'))]"
