      "dependsOn": [
        "[resourceId('Microsoft.Storage/storageAccounts/blobServices/containers', variables('validatedStorageAccountName'), 'default', variables('containerName'))]",
        "[resourceId('Microsoft.Authorization/roleDefinitions', variables('runtimeLeaseDataRoleDefinitionGuid'))]"
      ]
    }
  ],
