      "type": "string",
      "value": "[extensionResourceId(resourceId('Microsoft.Storage/storageAccounts/blobServices/containers', variables('validatedStorageAccountName'), 'default', variables('containerName')), 'Microsoft.Authorization/roleAssignments', guid(resourceId('Microsoft.Storage/storageAccounts/blobServices/containers', variables('validatedStorageAccountName'), 'default', variables('containerName')), variables('validatedBootstrapPrincipalId'), resourceId('Microsoft.Authorization/roleDefinitions', variables('bootstrapLeaseDataRoleDefinitionGuid')), variables('leaseBlobPath')))]"
